-- RFC-016 fase 3b — lender platform fee (5% of principal + IVA 16%).
-- Table + SPs generated by posgmo-factory (tests/prd_platformFee.json), fixed by hand:
--   commit on every exit path (only the SP's own transaction), set_intent action,
--   explicit webhook transitions, by_loan/request_refund as one JSON value,
--   request_refund resolves companyId from the fee, sp_one scoped to company.
-- Validated on the live server inside a rolled-back transaction (2026-11-20).
-- Apply ONCE, after confirming the target DB ([appEnv] banner / LOCAL_DB_NAME).

-- PRD Hint: Alter CHECK constraint on dbo.paymentHistory to include 'FEE'
-- This migration is required for the new 'FEE' subjectType for platform fees.
IF EXISTS (SELECT * FROM sys.check_constraints WHERE parent_object_id = OBJECT_ID('dbo.paymentHistory') AND name = 'CK_paymentHistory_subjectType')
BEGIN
    ALTER TABLE dbo.paymentHistory DROP CONSTRAINT CK_paymentHistory_subjectType;
END
GO
ALTER TABLE dbo.paymentHistory ADD CONSTRAINT CK_paymentHistory_subjectType CHECK (subjectType IN ('FUNDING','PAYMENT','FEE'));
GO

CREATE TABLE [dbo].[platformFees] (
    platformFeeId       INT IDENTITY(1,1) NOT NULL,
    companyId           INT NOT NULL,
    loanId              INT NOT NULL,
    lenderClientId      INT NOT NULL,
    methodId            INT NULL,
    baseAmount          DECIMAL(10,2) NOT NULL,
    feeRateBps          INT NOT NULL,
    feeAmount           DECIMAL(10,2) NOT NULL,
    ivaRateBps          INT NOT NULL,
    ivaAmount           DECIMAL(10,2) NOT NULL,
    totalAmount         DECIMAL(10,2) NOT NULL,
    currency            NVARCHAR(3) NOT NULL,
    status              NVARCHAR(20) NOT NULL DEFAULT 'PENDING',
    stripePaymentIntentId NVARCHAR(100) NULL,
    stripeRefundId      NVARCHAR(100) NULL,
    failureReason       NVARCHAR(300) NULL,
    chargedAt           DATETIME NULL,
    paidAt              DATETIME NULL,
    refundedAt          DATETIME NULL,
    cfdiUuid            NVARCHAR(36) NULL,
    created_At          DATETIME NOT NULL DEFAULT GETDATE(),
    updated_at          DATETIME NULL,
    CONSTRAINT PK_platformFees PRIMARY KEY CLUSTERED (platformFeeId ASC),
    CONSTRAINT FK_platformFees_loans FOREIGN KEY (loanId) REFERENCES dbo.loans(loanId),
    CONSTRAINT FK_platformFees_clients FOREIGN KEY (lenderClientId) REFERENCES dbo.clients(clientId),
    CONSTRAINT FK_platformFees_savedPaymentMethods FOREIGN KEY (methodId) REFERENCES dbo.savedPaymentMethods(methodId),
    CONSTRAINT UQ_platformFees_companyId_loanId UNIQUE (companyId, loanId),
    CONSTRAINT CK_platformFees_baseAmount_Positive CHECK (baseAmount > 0),
    CONSTRAINT CK_platformFees_feeAmount_NonNegative CHECK (feeAmount >= 0),
    CONSTRAINT CK_platformFees_ivaAmount_NonNegative CHECK (ivaAmount >= 0),
    CONSTRAINT CK_platformFees_totalAmount_Calculation CHECK (totalAmount = feeAmount + ivaAmount)
);
GO

-- Indexes from specification and gate_result
CREATE NONCLUSTERED INDEX IX_platformFees_companyId ON dbo.platformFees (companyId);
CREATE NONCLUSTERED INDEX IX_platformFees_created_At ON dbo.platformFees (created_At);
CREATE NONCLUSTERED INDEX IX_platformFees_loanId ON dbo.platformFees (loanId);
CREATE NONCLUSTERED INDEX IX_platformFees_lenderClientId ON dbo.platformFees (lenderClientId);
CREATE NONCLUSTERED INDEX IX_platformFees_methodId ON dbo.platformFees (methodId);
CREATE NONCLUSTERED INDEX IX_platformFees_status ON dbo.platformFees (status);
-- Filtered UNIQUE index from PRD hint
CREATE UNIQUE NONCLUSTERED INDEX UQ_platformFees_stripePaymentIntentId ON dbo.platformFees (stripePaymentIntentId) WHERE stripePaymentIntentId IS NOT NULL;
GO

CREATE OR ALTER PROCEDURE [dbo].[sp_platformFees]
    @pjsonfile VARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    -- Transactions open when called (a caller's own transaction): early exits
    -- commit only the one this procedure opened, never the caller's.
    DECLARE @startTranCount INT = @@TRANCOUNT;

    DECLARE @Outputmessage NVARCHAR(MAX) = '{
      "result": [
        { "value": "", "msg": "", "error": "" }
      ]
    }';

    DECLARE @action NVARCHAR(50);
    SET @action = (SELECT TOP 1 JSON_VALUE(value, '$.action') FROM OPENJSON(@pjsonfile, '$.platformFees'));

    DECLARE @payload TABLE (
        platformFeeId         INT NULL,
        companyId             INT NULL,
        loanId                INT NULL,
        lenderClientId        INT NULL,
        methodId              INT NULL,
        baseAmount            DECIMAL(10,2) NULL,
        feeRateBps            INT NULL,
        feeAmount             DECIMAL(10,2) NULL,
        ivaRateBps            INT NULL,
        ivaAmount             DECIMAL(10,2) NULL,
        totalAmount           DECIMAL(10,2) NULL,
        currency              NVARCHAR(3) NULL,
        status                NVARCHAR(20) NULL,
        stripePaymentIntentId NVARCHAR(100) NULL,
        stripeRefundId        NVARCHAR(100) NULL,
        failureReason         NVARCHAR(300) NULL,
        chargedAt             DATETIME NULL,
        paidAt                DATETIME NULL,
        refundedAt            DATETIME NULL,
        cfdiUuid              NVARCHAR(36) NULL,
        actorUserId           INT NULL,
        reason                NVARCHAR(500) NULL
    );

    INSERT INTO @payload (
        platformFeeId, companyId, loanId, lenderClientId, methodId, status,
        stripePaymentIntentId, stripeRefundId, failureReason, chargedAt, paidAt, refundedAt, cfdiUuid,
        actorUserId, reason
    )
    SELECT
        TRY_CONVERT(INT, JSON_VALUE(value, '$.platformFeeId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.loanId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.lenderClientId')),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.methodId')),
        JSON_VALUE(value, '$.status'),
        JSON_VALUE(value, '$.stripePaymentIntentId'),
        JSON_VALUE(value, '$.stripeRefundId'),
        JSON_VALUE(value, '$.failureReason'),
        TRY_CONVERT(DATETIME, JSON_VALUE(value, '$.chargedAt')),
        TRY_CONVERT(DATETIME, JSON_VALUE(value, '$.paidAt')),
        TRY_CONVERT(DATETIME, JSON_VALUE(value, '$.refundedAt')),
        JSON_VALUE(value, '$.cfdiUuid'),
        TRY_CONVERT(INT, JSON_VALUE(value, '$.actorUserId')),
        JSON_VALUE(value, '$.reason')
    FROM OPENJSON(@pjsonfile, '$.platformFees');

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @action = 'insert' OR @action = '1'
        BEGIN
            DECLARE @l_companyId INT, @l_loanId INT, @l_lenderClientId INT, @l_methodId INT, @l_actorUserId INT, @l_reason NVARCHAR(500);
            SELECT TOP 1 @l_companyId = companyId, @l_loanId = loanId, @l_lenderClientId = lenderClientId, @l_methodId = methodId, @l_actorUserId = actorUserId, @l_reason = reason FROM @payload;

            -- Validate mandatory fields for insert
            IF @l_companyId IS NULL OR @l_loanId IS NULL OR @l_lenderClientId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'companyId, loanId, and lenderClientId are required for insert.');
                GOTO Finish;
            END

            -- Check for duplicate (companyId, loanId)
            IF EXISTS (SELECT 1 FROM dbo.platformFees WHERE companyId = @l_companyId AND loanId = @l_loanId)
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'A platform fee for this loan already exists within the company.');
                GOTO Finish;
            END

            -- PRD Hint: Compute amounts from loans.principalAmount
            DECLARE @l_principalAmount DECIMAL(10,2);
            SELECT @l_principalAmount = L.principalAmount
            FROM dbo.loans L
            WHERE L.loanId = @l_loanId;

            IF @l_principalAmount IS NULL OR @l_principalAmount <= 0
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Loan principalAmount not found or invalid for calculation.');
                GOTO Finish;
            END

            -- Fixed rates as per PRD hint
            DECLARE @l_feeRateBps INT = 500; -- 5%
            DECLARE @l_ivaRateBps INT = 1600; -- 16%

            DECLARE @l_baseAmount DECIMAL(10,2) = @l_principalAmount;
            DECLARE @l_feeAmount DECIMAL(10,2) = ROUND(@l_baseAmount * @l_feeRateBps / 10000.0, 2);
            DECLARE @l_ivaAmount DECIMAL(10,2) = ROUND(@l_feeAmount * @l_ivaRateBps / 10000.0, 2);
            DECLARE @l_totalAmount DECIMAL(10,2) = @l_feeAmount + @l_ivaAmount;
            DECLARE @l_currency NVARCHAR(3) = 'MXN';
            DECLARE @l_status NVARCHAR(20) = 'PENDING';

            INSERT INTO dbo.platformFees (
                companyId, loanId, lenderClientId, methodId, baseAmount, feeRateBps, feeAmount, ivaRateBps, ivaAmount, totalAmount, currency, status, created_At
            )
            SELECT
                @l_companyId, @l_loanId, @l_lenderClientId, @l_methodId, @l_baseAmount, @l_feeRateBps, @l_feeAmount, @l_ivaRateBps, @l_ivaAmount, @l_totalAmount, @l_currency, @l_status, GETDATE();

            DECLARE @newPlatformFeeId INT = SCOPE_IDENTITY();

            -- Insert into paymentHistory (PRD Hint)
            INSERT INTO dbo.paymentHistory (companyId, subjectType, subjectId, oldStatus, newStatus, actorUserId, reason, created_At)
            VALUES (@l_companyId, 'FEE', @newPlatformFeeId, NULL, @l_status, @l_actorUserId, ISNULL(@l_reason, 'Initial creation'), GETDATE());

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', CAST(@newPlatformFeeId AS NVARCHAR(MAX)));
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee inserted successfully.');
        END
        ELSE IF @action = 'update' OR @action = '2'
        BEGIN
            DECLARE @u_platformFeeId INT, @u_companyId INT, @u_oldStatus NVARCHAR(20), @u_newStatus NVARCHAR(20);
            DECLARE @u_stripePaymentIntentId NVARCHAR(100), @u_stripeRefundId NVARCHAR(100), @u_failureReason NVARCHAR(300), @u_chargedAt DATETIME, @u_paidAt DATETIME, @u_refundedAt DATETIME, @u_cfdiUuid NVARCHAR(36);
            DECLARE @u_methodId INT, @u_loanId INT;
            DECLARE @u_actorUserId INT, @u_reason NVARCHAR(500);

            SELECT TOP 1
                @u_platformFeeId = platformFeeId, @u_companyId = companyId, @u_newStatus = status, @u_methodId = methodId,
                @u_stripePaymentIntentId = stripePaymentIntentId, @u_stripeRefundId = stripeRefundId, @u_failureReason = failureReason,
                @u_chargedAt = chargedAt, @u_paidAt = paidAt, @u_refundedAt = refundedAt, @u_cfdiUuid = cfdiUuid,
                @u_actorUserId = actorUserId, @u_reason = reason, @u_loanId = loanId
            FROM @payload;

            IF @u_platformFeeId IS NULL OR @u_companyId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'platformFeeId and companyId are required for update.');
                GOTO Finish;
            END

            -- Get current status for transition validation
            SELECT @u_oldStatus = status FROM dbo.platformFees WHERE platformFeeId = @u_platformFeeId AND companyId = @u_companyId;

            IF @u_oldStatus IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee not found for update.');
                GOTO Finish;
            END

            -- Status transition validation (PRD Hint)
            IF @u_newStatus IS NOT NULL AND @u_newStatus <> @u_oldStatus
            BEGIN
                IF (
                    (@u_oldStatus = 'PENDING' AND @u_newStatus NOT IN ('PAID', 'FAILED', 'REFUNDED')) OR
                    (@u_oldStatus = 'FAILED' AND @u_newStatus NOT IN ('PENDING', 'REFUNDED')) OR
                    (@u_oldStatus = 'PAID' AND @u_newStatus NOT IN ('REFUND_PENDING')) OR
                    (@u_oldStatus = 'REFUND_PENDING' AND @u_newStatus NOT IN ('REFUNDED')) OR
                    (@u_oldStatus IN ('REFUNDED') AND @u_newStatus NOT IN ('REFUNDED')) -- Terminal states
                )
                BEGIN
                    SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                    SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Invalid status transition from ' + @u_oldStatus + ' to ' + @u_newStatus);
                    GOTO Finish;
                END

                -- Specific validation for PAID -> REFUND_PENDING (PRD Hint)
                IF (@u_oldStatus = 'PAID' AND @u_newStatus = 'REFUND_PENDING')
                BEGIN
                    IF EXISTS (SELECT 1 FROM dbo.fundingTransactions WHERE loanId = @u_loanId AND status = 'CONFIRMED')
                    BEGIN
                        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Cannot request refund: loan has already been disbursed.');
                        GOTO Finish;
                    END
                END
            END

            UPDATE pf
            SET
                methodId = ISNULL(p.methodId, pf.methodId),
                status = ISNULL(p.status, pf.status),
                stripePaymentIntentId = ISNULL(p.stripePaymentIntentId, pf.stripePaymentIntentId),
                stripeRefundId = ISNULL(p.stripeRefundId, pf.stripeRefundId),
                failureReason = ISNULL(p.failureReason, pf.failureReason),
                chargedAt = ISNULL(p.chargedAt, pf.chargedAt),
                paidAt = ISNULL(p.paidAt, pf.paidAt),
                refundedAt = ISNULL(p.refundedAt, pf.refundedAt),
                cfdiUuid = ISNULL(p.cfdiUuid, pf.cfdiUuid),
                updated_at = GETDATE()
            FROM dbo.platformFees pf
            INNER JOIN @payload p ON pf.platformFeeId = p.platformFeeId AND pf.companyId = p.companyId;

            IF @u_newStatus IS NOT NULL AND @u_newStatus <> @u_oldStatus
            BEGIN
                -- Insert into paymentHistory on status change (PRD Hint)
                INSERT INTO dbo.paymentHistory (companyId, subjectType, subjectId, oldStatus, newStatus, actorUserId, reason, created_At)
                VALUES (@u_companyId, 'FEE', @u_platformFeeId, @u_oldStatus, @u_newStatus, @u_actorUserId, ISNULL(@u_reason, 'Status update'), GETDATE());
            END

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', CAST(@u_platformFeeId AS NVARCHAR(MAX)));
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee updated successfully.');
        END
        ELSE IF @action = 'delete' OR @action = '3'
        BEGIN
            DECLARE @d_platformFeeId INT, @d_companyId INT;
            SELECT TOP 1 @d_platformFeeId = platformFeeId, @d_companyId = companyId FROM @payload;

            IF @d_platformFeeId IS NULL OR @d_companyId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'platformFeeId and companyId are required for delete.');
                GOTO Finish;
            END

            DELETE FROM dbo.platformFees WHERE platformFeeId = @d_platformFeeId AND companyId = @d_companyId;

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', CAST(@d_platformFeeId AS NVARCHAR(MAX)));
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee deleted successfully.');
        END
        ELSE IF @action = 'by_loan' -- PRD Hint: Extra action 'by_loan'
        BEGIN
            DECLARE @bl_companyId INT, @bl_loanId INT;
            SELECT TOP 1 @bl_companyId = companyId, @bl_loanId = loanId FROM @payload;

            IF @bl_companyId IS NULL OR @bl_loanId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'companyId and loanId are required for ''by_loan'' action.');
                GOTO Finish;
            END

            SELECT (SELECT
                platformFeeId,
                ISNULL(companyId, 0) AS companyId,
                ISNULL(loanId, 0) AS loanId,
                ISNULL(lenderClientId, 0) AS lenderClientId,
                ISNULL(methodId, 0) AS methodId,
                ISNULL(baseAmount, 0.00) AS baseAmount,
                ISNULL(feeRateBps, 0) AS feeRateBps,
                ISNULL(feeAmount, 0.00) AS feeAmount,
                ISNULL(ivaRateBps, 0) AS ivaRateBps,
                ISNULL(ivaAmount, 0.00) AS ivaAmount,
                ISNULL(totalAmount, 0.00) AS totalAmount,
                ISNULL(currency, '') AS currency,
                ISNULL(status, '') AS status,
                ISNULL(stripePaymentIntentId, '') AS stripePaymentIntentId,
                ISNULL(stripeRefundId, '') AS stripeRefundId,
                ISNULL(failureReason, '') AS failureReason,
                created_At,
                ISNULL(CONVERT(VARCHAR(30), chargedAt, 126), '') AS chargedAt,
                ISNULL(CONVERT(VARCHAR(30), paidAt, 126), '') AS paidAt,
                ISNULL(CONVERT(VARCHAR(30), refundedAt, 126), '') AS refundedAt,
                ISNULL(cfdiUuid, '') AS cfdiUuid,
                ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
            FROM dbo.platformFees
            WHERE companyId = @bl_companyId AND loanId = @bl_loanId
            FOR JSON PATH, ROOT('platformFees')) AS jsonResult;

            IF @@TRANCOUNT > @startTranCount COMMIT TRANSACTION;
            GOTO Done; -- one result set: the JSON above
        END
        ELSE IF @action = 'mark_webhook' -- PRD Hint: Extra action 'mark_webhook'
        BEGIN
            DECLARE @mw_stripePaymentIntentId NVARCHAR(100), @mw_newStatus NVARCHAR(20);
            DECLARE @mw_failureReason NVARCHAR(300), @mw_stripeRefundId NVARCHAR(100);
            DECLARE @mw_actorUserId INT;
            DECLARE @mw_platformFeeId INT, @mw_companyId INT, @mw_oldStatus NVARCHAR(20), @mw_loanId INT;

            SELECT TOP 1
                @mw_stripePaymentIntentId = stripePaymentIntentId, @mw_newStatus = status, @mw_failureReason = failureReason,
                @mw_stripeRefundId = stripeRefundId, @mw_actorUserId = actorUserId
            FROM @payload;

            IF @mw_stripePaymentIntentId IS NULL OR @mw_newStatus IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'stripePaymentIntentId and newStatus are required for ''mark_webhook'' action.');
                GOTO Finish;
            END

            SELECT @mw_platformFeeId = platformFeeId, @mw_companyId = companyId, @mw_oldStatus = status, @mw_loanId = loanId
            FROM dbo.platformFees WHERE stripePaymentIntentId = @mw_stripePaymentIntentId;

            IF @mw_platformFeeId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee not found for given stripePaymentIntentId.');
                GOTO Finish;
            END

            -- Idempotency check
            IF @mw_newStatus = @mw_oldStatus
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Webhook already processed for this status. No changes made.');
                GOTO Finish;
            END

            -- Status transition validation (PRD Hint)
            IF NOT (
                (@mw_oldStatus = 'PENDING'        AND @mw_newStatus IN ('PAID', 'FAILED')) OR
                (@mw_oldStatus = 'FAILED'         AND @mw_newStatus IN ('PAID')) OR
                (@mw_oldStatus = 'PAID'           AND @mw_newStatus IN ('REFUNDED')) OR
                (@mw_oldStatus = 'REFUND_PENDING' AND @mw_newStatus IN ('REFUNDED'))
            )
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', @mw_oldStatus);
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Invalid webhook status transition from ' + @mw_oldStatus + ' to ' + @mw_newStatus);
                GOTO Finish;
            END

            UPDATE dbo.platformFees
            SET
                status = @mw_newStatus,
                failureReason = CASE WHEN @mw_newStatus = 'FAILED' THEN ISNULL(@mw_failureReason, failureReason) ELSE NULL END,
                paidAt = CASE WHEN @mw_newStatus = 'PAID' THEN GETDATE() ELSE paidAt END,
                refundedAt = CASE WHEN @mw_newStatus = 'REFUNDED' THEN GETDATE() ELSE refundedAt END,
                stripeRefundId = CASE WHEN @mw_newStatus = 'REFUNDED' THEN ISNULL(@mw_stripeRefundId, stripeRefundId) ELSE stripeRefundId END,
                updated_at = GETDATE()
            WHERE platformFeeId = @mw_platformFeeId;

            -- Insert into paymentHistory on status change (PRD Hint)
            INSERT INTO dbo.paymentHistory (companyId, subjectType, subjectId, oldStatus, newStatus, actorUserId, reason, created_At)
            VALUES (@mw_companyId, 'FEE', @mw_platformFeeId, @mw_oldStatus, @mw_newStatus, @mw_actorUserId, 'Webhook update to ' + @mw_newStatus, GETDATE());

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', CAST(@mw_platformFeeId AS NVARCHAR(MAX)));
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee updated via webhook successfully.');
        END
        ELSE IF @action = 'set_intent' -- store the Stripe PaymentIntent id + attempt time (no status change)
        BEGIN
            DECLARE @si_platformFeeId INT, @si_companyId INT, @si_pi NVARCHAR(100), @si_failureReason NVARCHAR(300);
            SELECT TOP 1 @si_platformFeeId = platformFeeId, @si_companyId = companyId,
                         @si_pi = stripePaymentIntentId, @si_failureReason = failureReason
            FROM @payload;

            IF @si_platformFeeId IS NULL OR @si_companyId IS NULL OR @si_pi IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'platformFeeId, companyId and stripePaymentIntentId are required for ''set_intent''.');
                GOTO Finish;
            END

            UPDATE dbo.platformFees
            SET stripePaymentIntentId = @si_pi,
                failureReason = @si_failureReason,
                chargedAt = GETDATE(),
                updated_at = GETDATE()
            WHERE platformFeeId = @si_platformFeeId AND companyId = @si_companyId
              AND (stripePaymentIntentId IS NULL OR stripePaymentIntentId = @si_pi);

            IF @@ROWCOUNT = 0
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee not found, or it already has a different PaymentIntent.');
                GOTO Finish;
            END

            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].value', CAST(@si_platformFeeId AS NVARCHAR(MAX)));
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'PaymentIntent stored.');
        END
        ELSE IF @action = 'request_refund' -- PRD Hint: Extra action 'request_refund'
        BEGIN
            DECLARE @rr_loanId INT, @rr_companyId INT, @rr_reason NVARCHAR(500), @rr_actorUserId INT;
            DECLARE @rr_platformFeeId INT, @rr_status NVARCHAR(20), @rr_stripePaymentIntentId NVARCHAR(100), @rr_lenderClientId INT;

            SELECT TOP 1 @rr_loanId = loanId, @rr_companyId = companyId, @rr_reason = reason, @rr_actorUserId = actorUserId FROM @payload;

            -- The expiry cron only knows the loanId: take the company from the fee row
            -- (loanId is dbo.loans' identity, so it is unique across companies).
            IF @rr_companyId IS NULL AND @rr_loanId IS NOT NULL
                SELECT TOP 1 @rr_companyId = companyId FROM dbo.platformFees WHERE loanId = @rr_loanId;

            IF @rr_loanId IS NULL OR @rr_companyId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'loanId and companyId are required for ''request_refund'' action.');
                GOTO Finish;
            END

            -- PRD Hint: Check dbo.fundingTransactions for CONFIRMED row
            IF EXISTS (SELECT 1 FROM dbo.fundingTransactions WHERE loanId = @rr_loanId AND status = 'CONFIRMED')
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Cannot request refund: loan has already been disbursed.');
                GOTO Finish;
            END

            SELECT TOP 1
                @rr_platformFeeId = platformFeeId,
                @rr_status = status,
                @rr_stripePaymentIntentId = stripePaymentIntentId,
                @rr_lenderClientId = lenderClientId
            FROM dbo.platformFees
            WHERE companyId = @rr_companyId AND loanId = @rr_loanId;

            IF @rr_platformFeeId IS NULL
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Platform fee not found for this loan.');
                GOTO Finish;
            END

            -- Update status to REFUNDED for PENDING/FAILED, REFUND_PENDING for PAID
            DECLARE @new_refund_status NVARCHAR(20);
            IF @rr_status IN ('PENDING', 'FAILED')
                SET @new_refund_status = 'REFUNDED';
            ELSE IF @rr_status = 'PAID'
                SET @new_refund_status = 'REFUND_PENDING';
            ELSE
            BEGIN
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
                SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Cannot request refund from current status: ' + @rr_status);
                GOTO Finish;
            END

            UPDATE dbo.platformFees
            SET
                status = @new_refund_status,
                refundedAt = CASE WHEN @new_refund_status = 'REFUNDED' THEN GETDATE() ELSE refundedAt END,
                updated_at = GETDATE()
            WHERE platformFeeId = @rr_platformFeeId;

            -- Insert into paymentHistory on status change
            INSERT INTO dbo.paymentHistory (companyId, subjectType, subjectId, oldStatus, newStatus, actorUserId, reason, created_At)
            VALUES (@rr_companyId, 'FEE', @rr_platformFeeId, @rr_status, @new_refund_status, @rr_actorUserId, ISNULL(@rr_reason, 'Refund requested'), GETDATE());

            -- Return relevant info for backend Stripe call
            SELECT (SELECT
                @rr_platformFeeId AS platformFeeId,
                @rr_companyId AS companyId,
                @rr_loanId AS loanId,
                @rr_lenderClientId AS lenderClientId,
                @rr_status AS previousStatus,
                @new_refund_status AS status,
                ISNULL(@rr_stripePaymentIntentId, '') AS stripePaymentIntentId
            FOR JSON PATH, ROOT('platformFees')) AS jsonResult;

            IF @@TRANCOUNT > @startTranCount COMMIT TRANSACTION;
            GOTO Done; -- one result set: the JSON above
        END
        ELSE
        BEGIN
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
            SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', 'Invalid action specified.');
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].error', '1');
        SET @Outputmessage = JSON_MODIFY(@Outputmessage, '$.result[0].msg', ERROR_MESSAGE());
    END CATCH;

Finish:
    IF @@TRANCOUNT > @startTranCount COMMIT TRANSACTION;
    SELECT
        JSON_VALUE(value, '$.value') AS value,
        JSON_VALUE(value, '$.msg') AS msg,
        JSON_VALUE(value, '$.error') AS error
    FROM OPENJSON(@Outputmessage, '$.result');
Done:
    RETURN;
END;
GO

CREATE OR ALTER PROC [dbo].[sp_platformFees_all] (@pjsonfile VARCHAR(MAX))
AS
SET NOCOUNT ON;
BEGIN
    DECLARE @companyId INT;
    SET @companyId = TRY_CONVERT(INT,
        (SELECT TOP 1 JSON_VALUE(value, '$.companyId')
         FROM OPENJSON(@pjsonfile, '$.platformFees'))
    );

    SELECT
        [platformFeeId],
        ISNULL([companyId], 0) AS companyId,
        ISNULL([loanId], 0) AS loanId,
        ISNULL([lenderClientId], 0) AS lenderClientId,
        ISNULL([methodId], 0) AS methodId,
        ISNULL([baseAmount], 0.00) AS baseAmount,
        ISNULL([feeRateBps], 0) AS feeRateBps,
        ISNULL([feeAmount], 0.00) AS feeAmount,
        ISNULL([ivaRateBps], 0) AS ivaRateBps,
        ISNULL([ivaAmount], 0.00) AS ivaAmount,
        ISNULL([totalAmount], 0.00) AS totalAmount,
        ISNULL([currency], '') AS currency,
        ISNULL([status], '') AS status,
        ISNULL([stripePaymentIntentId], '') AS stripePaymentIntentId,
        ISNULL([stripeRefundId], '') AS stripeRefundId,
        ISNULL([failureReason], '') AS failureReason,
        [created_At],
        ISNULL(CONVERT(VARCHAR(30), chargedAt, 126), '') AS chargedAt,
        ISNULL(CONVERT(VARCHAR(30), paidAt, 126), '') AS paidAt,
        ISNULL(CONVERT(VARCHAR(30), refundedAt, 126), '') AS refundedAt,
        ISNULL([cfdiUuid], '') AS cfdiUuid,
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.platformFees
    WHERE companyId = @companyId
    ORDER BY created_At DESC
    FOR JSON AUTO, ROOT('platformFees');
END;
GO


CREATE OR ALTER PROC [dbo].[sp_platformFees_one] (@pjsonfile VARCHAR(MAX))
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @platformFeeId INT, @companyId INT;
    SET @companyId = TRY_CONVERT(INT,
        (SELECT TOP 1 JSON_VALUE(value, '$.companyId') FROM OPENJSON(@pjsonfile, '$.platformFees')));
    SET @platformFeeId = CAST(
        (SELECT TOP 1 JSON_VALUE(value, '$.platformFeeId')
         FROM OPENJSON(@pjsonfile, '$.platformFees')) AS INT
    );
    SELECT
        platformFeeId,
        ISNULL(companyId, 0) AS companyId,
        ISNULL(loanId, 0) AS loanId,
        ISNULL(lenderClientId, 0) AS lenderClientId,
        ISNULL(methodId, 0) AS methodId,
        ISNULL(baseAmount, 0.00) AS baseAmount,
        ISNULL(feeRateBps, 0) AS feeRateBps,
        ISNULL(feeAmount, 0.00) AS feeAmount,
        ISNULL(ivaRateBps, 0) AS ivaRateBps,
        ISNULL(ivaAmount, 0.00) AS ivaAmount,
        ISNULL(totalAmount, 0.00) AS totalAmount,
        ISNULL(currency, '') AS currency,
        ISNULL(status, '') AS status,
        ISNULL(stripePaymentIntentId, '') AS stripePaymentIntentId,
        ISNULL(stripeRefundId, '') AS stripeRefundId,
        ISNULL(failureReason, '') AS failureReason,
        created_At,
        ISNULL(CONVERT(VARCHAR(30), chargedAt, 126), '') AS chargedAt,
        ISNULL(CONVERT(VARCHAR(30), paidAt, 126), '') AS paidAt,
        ISNULL(CONVERT(VARCHAR(30), refundedAt, 126), '') AS refundedAt,
        ISNULL(cfdiUuid, '') AS cfdiUuid,
        ISNULL(CONVERT(VARCHAR(30), updated_at, 126), '') AS updated_at
    FROM dbo.platformFees
    WHERE platformFeeId = @platformFeeId AND companyId = @companyId
    FOR JSON AUTO, ROOT('platformFees');
END;
GO